import React from 'react';
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import RegistrationStep1 from './RegistrationStep1';
import RegistrationStep2 from './RegistrationStep2';
import Login from './Login';
import Homepage from './pages/Homepage';
import LandingPage from './pages/LandingPage';
import ProfileSection from '../Profile Management - Kris/src/ProfileSection'; // Update import path

function App() {
    return (
        <Router>
            <Routes>
                <Route path="/" element={<LandingPage />} /> {/* Update root path to LandingPage */}
                <Route path="/homepage" element={<Homepage />} /> {/* Add Homepage route */}
                <Route path="/step1" element={<RegistrationStep1 />} />
                <Route path="/step2" element={<RegistrationStep2 />} />
                <Route path="/login" element={<Login />} />
                <Route path="/profile" element={<ProfileSection />} /> {/* Add ProfileSection route */}
            </Routes>
        </Router>
    );
}

export default App;
